INSERT INTO cafe_menu_items (id, category_id, name, description, price, image, calories, is_popular, is_active, sort_order, created_at, updated_at) VALUES (1, 1, 'Artisan Caffè Americano', 'Rich espresso shots topped with hot water create a light layer of crema and deep aromatic roast notes.', 695.0, 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?auto=format&fit=crop&w=600&q=80', '15 kcal', 1, TRUE, 1, '2026-08-20 20:14:16.954224', '2026-08-20 20:14:16.954227') ON CONFLICT DO NOTHING;
INSERT INTO cafe_menu_items (id, category_id, name, description, price, image, calories, is_popular, is_active, sort_order, created_at, updated_at) VALUES (2, 1, 'Café Latte', 'Rich espresso balanced with velvety steamed milk and a thin layer of microfoam.', 895.0, 'https://images.unsplash.com/photo-1570968915860-54d5c301fa9f?auto=format&fit=crop&w=600&q=80', '190 kcal', 1, TRUE, 2, '2026-08-20 20:14:16.954229', '2026-08-20 20:14:16.954230') ON CONFLICT DO NOTHING;
INSERT INTO cafe_menu_items (id, category_id, name, description, price, image, calories, is_popular, is_active, sort_order, created_at, updated_at) VALUES (3, 1, 'Cappuccino', 'Bold espresso crowned with dense, luxurious foam and dusted with cocoa.', 895.0, 'https://images.unsplash.com/photo-1534778101976-62847782c213?auto=format&fit=crop&w=600&q=80', '160 kcal', 1, TRUE, 3, '2026-08-20 20:14:16.954231', '2026-08-20 20:14:16.954232') ON CONFLICT DO NOTHING;
INSERT INTO cafe_menu_items (id, category_id, name, description, price, image, calories, is_popular, is_active, sort_order, created_at, updated_at) VALUES (4, 2, 'The Original Mocha Ice Blended®', 'Special Dutch chocolate, coffee extract, skim milk, and crushed ice with whipped cream.', 1150.0, 'https://images.unsplash.com/photo-1517256064527-09c73fc73e38?auto=format&fit=crop&w=600&q=80', '420 kcal', 1, TRUE, 1, '2026-08-20 20:14:16.954234', '2026-08-20 20:14:16.954235') ON CONFLICT DO NOTHING;
INSERT INTO cafe_menu_items (id, category_id, name, description, price, image, calories, is_popular, is_active, sort_order, created_at, updated_at) VALUES (5, 2, 'Caramel Ice Blended®', 'Sweet buttery caramel blended with milk, coffee and ice, topped with whipped cream.', 1150.0, 'https://images.unsplash.com/photo-1577805947697-89e18249d767?auto=format&fit=crop&w=600&q=80', '410 kcal', 0, TRUE, 2, '2026-08-20 20:14:16.954236', '2026-08-20 20:14:16.954238') ON CONFLICT DO NOTHING;
INSERT INTO cafe_menu_items (id, category_id, name, description, price, image, calories, is_popular, is_active, sort_order, created_at, updated_at) VALUES (6, 3, 'Texan BBQ Chicken Burger', 'Crispy seasoned chicken breast tossed in smoky Texan BBQ sauce with cheddar cheese & fries.', 1350.0, 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=600&q=80', '690 kcal', 1, TRUE, 1, '2026-08-20 20:14:16.954239', '2026-08-20 20:14:16.954240') ON CONFLICT DO NOTHING;
INSERT INTO cafe_menu_items (id, category_id, name, description, price, image, calories, is_popular, is_active, sort_order, created_at, updated_at) VALUES (7, 4, 'LA Club Sandwich', 'Triple decker toasted sandwich with roasted chicken, fried egg, cheese, lettuce & tomato.', 1250.0, 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=600&q=80', '580 kcal', 1, TRUE, 1, '2026-08-20 20:14:16.954242', '2026-08-20 20:14:16.954243') ON CONFLICT DO NOTHING;
INSERT INTO cafe_menu_items (id, category_id, name, description, price, image, calories, is_popular, is_active, sort_order, created_at, updated_at) VALUES (8, 5, 'Belgian Dark Chocolate Fudge Cake', 'Layers of rich dark chocolate sponge smothered with warm Belgian fudge ganache.', 780.0, 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=600&q=80', '480 kcal', 1, TRUE, 1, '2026-08-20 20:14:16.954244', '2026-08-20 20:14:16.954246') ON CONFLICT DO NOTHING;
