INSERT INTO banners (id, title, subtitle, description, image, button_text, button_url, badge_text, banner_type, is_active, sort_order, created_at, updated_at) VALUES (1, 'Masterfully Roasted Coffee Beans', 'The Top 1% Arabica from the World''s Best High-Altitude Estates', 'Explore our hand-roasted collection: from bright floral Costa Rican origins to deeply rich Sumatra dark roasts. Freshly packed & shipped across Pakistan.', 'https://images.unsplash.com/photo-1447933601403-0c6688de566e?auto=format&fit=crop&w=1600&q=85', 'Shop Coffee Collection', '/shop/coffee', 'Direct Trade Arabica', 'hero', TRUE, 1, '2026-08-20 20:14:16.955553', '2026-08-20 20:14:16.955556') ON CONFLICT DO NOTHING;
INSERT INTO banners (id, title, subtitle, description, image, button_text, button_url, badge_text, banner_type, is_active, sort_order, created_at, updated_at) VALUES (2, 'The World''s Original Ice Blended®', 'Invented by The Coffee Bean & Tea Leaf in 1987', 'Creamy espresso, rich Dutch chocolate, and vanilla blended with crushed ice and crowned with whipped cream. Visit your nearest cafe today.', 'https://images.unsplash.com/photo-1517256064527-09c73fc73e38?auto=format&fit=crop&w=1600&q=85', 'Explore Cafe Menu', '/cafe-menu', 'Iconic Beverly Hills Recipe', 'hero', TRUE, 2, '2026-08-20 20:14:16.955558', '2026-08-20 20:14:16.955559') ON CONFLICT DO NOTHING;
INSERT INTO banners (id, title, subtitle, description, image, button_text, button_url, badge_text, banner_type, is_active, sort_order, created_at, updated_at) VALUES (3, 'Hand-Plucked Whole Leaf Teas', 'Single-Estate Reserve Black, Green & Herbal Infusions', 'Crafted with pure top two leaves and a bud for exceptional depth, delicate sweetness, and vibrant health benefits.', 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?auto=format&fit=crop&w=1600&q=85', 'Shop Tea Blends', '/shop/tea', '100% Whole Leaf', 'hero', TRUE, 3, '2026-08-20 20:14:16.955561', '2026-08-20 20:14:16.955562') ON CONFLICT DO NOTHING;
INSERT INTO banners (id, title, subtitle, description, image, button_text, button_url, badge_text, banner_type, is_active, sort_order, created_at, updated_at) VALUES (4, 'Free Express Shipping', 'Nationwide delivery on all orders over Rs. 3,500', 'Roasted fresh, securely packed, and delivered to your doorstep.', 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?auto=format&fit=crop&w=800&q=80', 'Start Shopping', '/shop', 'Free Shipping', 'promotional', TRUE, 1, '2026-08-20 20:14:16.955564', '2026-08-20 20:14:16.955565') ON CONFLICT DO NOTHING;
INSERT INTO banners (id, title, subtitle, description, image, button_text, button_url, badge_text, banner_type, is_active, sort_order, created_at, updated_at) VALUES (5, 'Freshly Brewed in Our Cafes', 'Find your nearest Coffee Bean store in Islamabad, Lahore, Karachi & more', 'Unwind in welcoming ambience with artisan espresso, gourmet meals, and fast WiFi.', 'https://images.unsplash.com/photo-1554118811-1e0d58224f24?auto=format&fit=crop&w=800&q=80', 'Locate a Store', '/stores', 'Store Locator', 'promotional', TRUE, 2, '2026-08-20 20:14:16.955566', '2026-08-20 20:14:16.955567') ON CONFLICT DO NOTHING;
